import { useState, useEffect } from 'react';
const API = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');

export default function StudentsPanel({ store }) {
  const [students, setStudents] = useState([]);
  const [loading,  setLoading]  = useState(true);
  const [search,   setSearch]   = useState('');

  useEffect(() => {
    fetch(`${API}/students`, { headers:{ Authorization:`Bearer ${getToken()}` } })
      .then(r=>r.json()).then(d=>{ setStudents(Array.isArray(d)?d:[]); setLoading(false); }).catch(()=>setLoading(false));
  }, []);

  const filtered = students.filter(s =>
    s.name?.toLowerCase().includes(search.toLowerCase()) ||
    s.email?.toLowerCase().includes(search.toLowerCase()) ||
    s.department?.toLowerCase().includes(search.toLowerCase())
  );
  const gc = g => g==='A+'||g==='A'?'#16a34a':g==='F'?'#dc2626':g==='B'?'#2563eb':'#d97706';

  return (
    <div className="fade-up">
      {/* Header — matches Image 4 */}
      <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:28, color:'#0f0f1a', marginBottom:6 }}>Students</h1>
      <p style={{ fontSize:13, color:'#7c3aed', fontFamily:'JetBrains Mono,monospace', marginBottom:24 }}>
        Showing {filtered.length} student{filtered.length!==1?'s':''} who have taken your exams
      </p>

      {/* Search */}
      {students.length > 0 && (
        <div style={{ position:'relative', marginBottom:20, maxWidth:400 }}>
          <span style={{ position:'absolute', left:12, top:'50%', transform:'translateY(-50%)', color:'#9ca3af', fontSize:14 }}>🔍</span>
          <input className="form-input" style={{ paddingLeft:38 }} placeholder="Search by name, email, department..."
            value={search} onChange={e=>setSearch(e.target.value)}/>
        </div>
      )}

      {loading ? (
        <div style={{ display:'flex', alignItems:'center', gap:12, padding:60, justifyContent:'center' }}>
          <div className="spinner" style={{width:28,height:28}}/><span style={{color:'#6b7280',fontSize:14}}>Loading students...</span>
        </div>
      ) : filtered.length === 0 ? (
        /* Empty state matches Image 4 exactly */
        <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 0' }}>
          <div style={{ fontSize:64, opacity:.2, marginBottom:16 }}>👥</div>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:18, color:'#374151', marginBottom:8 }}>
            {search ? 'No students match your search' : 'No students yet'}
          </div>
          <div style={{ fontSize:13, color:'#7c3aed', fontFamily:'JetBrains Mono,monospace', textAlign:'center' }}>
            {search ? 'Try a different search term' : 'Students will appear here after they take one of your published exams'}
          </div>
        </div>
      ) : (
        <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
          <table style={{ width:'100%', borderCollapse:'collapse' }}>
            <thead>
              <tr style={{ background:'#f8f8fc' }}>
                {['#','STUDENT','EMAIL','DEPARTMENT','YEAR','EXAMS TAKEN','BEST GRADE'].map(h => (
                  <th key={h} style={{ padding:'10px 16px', textAlign:'left', fontSize:9, fontWeight:700, color:'#9ca3af', textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace', borderBottom:'1px solid #f3f4f6' }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map((s, i) => {
                const color = gc(s.best_grade);
                return (
                  <tr key={s.student_id||i} style={{ borderBottom:'1px solid #f3f4f6', transition:'background .15s' }}
                    onMouseEnter={e=>e.currentTarget.style.background='#f8f8fc'}
                    onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                    <td style={{ padding:'12px 16px', fontSize:12, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>{i+1}</td>
                    <td style={{ padding:'12px 16px' }}>
                      <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                        <div style={{ width:32, height:32, borderRadius:'50%', background:'linear-gradient(135deg,#ede9fe,#ddd6fe)', border:'1px solid #ddd6fe', display:'flex', alignItems:'center', justifyContent:'center', fontSize:13, fontWeight:800, color:'#7c3aed', flexShrink:0 }}>
                          {s.name?.charAt(0).toUpperCase()}
                        </div>
                        <span style={{ fontWeight:700, fontSize:13, color:'#0f0f1a' }}>{s.name}</span>
                      </div>
                    </td>
                    <td style={{ padding:'12px 16px', fontSize:12, color:'#6b7280', fontFamily:'JetBrains Mono,monospace' }}>{s.email}</td>
                    <td style={{ padding:'12px 16px', fontSize:12, color:'#374151' }}>{s.department||'—'}</td>
                    <td style={{ padding:'12px 16px', fontSize:12, color:'#374151' }}>{s.year||'—'}</td>
                    <td style={{ padding:'12px 16px', fontFamily:'JetBrains Mono,monospace', fontWeight:700, fontSize:13, color:'#7c3aed' }}>{s.exam_count||0}</td>
                    <td style={{ padding:'12px 16px' }}>
                      {s.best_grade
                        ? <span style={{ padding:'3px 10px', borderRadius:5, background:`${color}15`, color, fontSize:11, fontWeight:800 }}>{s.best_grade}</span>
                        : <span style={{ color:'#9ca3af', fontSize:12 }}>—</span>}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
